import { useState, useMemo } from 'react';
import { ChevronUp, ChevronDown, Search, Filter, ChevronLeft, ChevronRight, Check, CheckSquare, Square } from 'lucide-react';

interface Column<T> {
  key: string;
  header: string;
  render?: (row: T) => React.ReactNode;
  sortable?: boolean;
  className?: string;
}

interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  searchable?: boolean;
  sortable?: boolean;
  pagination?: boolean;
  pageSize?: number;
  selectable?: boolean;
  onSelectionChange?: (selected: T[]) => void;
  emptyMessage?: string;
  className?: string;
}

export default function DataTable<T extends { id: string | number }>(
  {
    data,
    columns,
    searchable = true,
    sortable = true,
    pagination = true,
    pageSize = 10,
    selectable = false,
    onSelectionChange,
    emptyMessage = "No data available",
    className = '',
  }: DataTableProps<T>
) {
  const [search, setSearch] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedRows, setSelectedRows] = useState<Set<string | number>>(new Set());

  const filteredData = useMemo(() => {
    let result = data;
    if (search) {
      const lowerSearch = search.toLowerCase();
      result = result.filter(row =>
        Object.values(row).some(val =>
          String(val).toLowerCase().includes(lowerSearch)
        )
      );
    }
    if (sortConfig) {
      result = [...result].sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return result;
  }, [data, search, sortConfig]);

  const paginatedData = useMemo(() => {
    if (!pagination) return filteredData;
    const start = (currentPage - 1) * pageSize;
    return filteredData.slice(start, start + pageSize);
  }, [filteredData, pagination, pageSize, currentPage]);

  const totalPages = Math.ceil(filteredData.length / pageSize);

  const handleSort = (key: string) => {
    if (!sortable) return;
    setSortConfig(prev => ({
      key,
      direction: prev?.key === key && prev.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const handleSelectAll = () => {
    if (selectedRows.size === paginatedData.length) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(paginatedData.map(row => row.id)));
    }
  };

  const handleRowSelect = (id: string | number) => {
    setSelectedRows(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleSelectionChange = () => {
    const selectedData = data.filter(row => selectedRows.has(row.id));
    onSelectionChange?.(selectedData);
  };

  return (
    <div className={`backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl overflow-hidden ${className}`}>
      {searchable && (
        <div className="p-4 border-b border-white/10">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="text"
              placeholder="Search..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-violet-500/50"
            />
          </div>
        </div>
      )}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-white/5">
            <tr>
              {selectable && (
                <th className="p-3 text-left">
                  <button
                    onClick={handleSelectAll}
                    className="flex items-center justify-center w-5 h-5 rounded border border-white/20 hover:bg-white/10 transition-colors"
                  >
                    {selectedRows.size === paginatedData.length && paginatedData.length > 0 ? (
                      <Check className="w-3.5 h-3.5 text-violet-400" />
                    ) : (
                      <Square className="w-3.5 h-3.5 text-gray-500" />
                    )}
                  </button>
                </th>
              )}
              {columns.map(col => (
                <th
                  key={col.key}
                  className={`p-3 text-left text-xs font-semibold text-gray-400 uppercase tracking-wider ${col.className || ''} ${col.sortable ? 'cursor-pointer hover:text-white select-none' : ''}`}
                  onClick={() => col.sortable && handleSort(col.key)}
                >
                  <div className="flex items-center gap-1">
                    {col.header}
                    {col.sortable && sortConfig?.key === col.key && (
                      sortConfig.direction === 'asc' ? (
                        <ChevronUp className="w-3.5 h-3.5 text-violet-400" />
                      ) : (
                        <ChevronDown className="w-3.5 h-3.5 text-violet-400" />
                      )
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length + (selectable ? 1 : 0)} className="px-4 py-12 text-center text-gray-500">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              paginatedData.map((row, rowIndex) => (
                <tr
                  key={row.id}
                  className="hover:bg-white/5 transition-colors"
                >
                  {selectable && (
                    <td className="p-3">
                      <button
                        onClick={() => handleRowSelect(row.id)}
                        className="flex items-center justify-center w-5 h-5 rounded border border-white/20 hover:bg-white/10 transition-colors"
                      >
                        {selectedRows.has(row.id) ? (
                          <Check className="w-3.5 h-3.5 text-violet-400" />
                        ) : (
                          <Square className="w-3.5 h-3.5 text-gray-500" />
                        )}
                      </button>
                    </td>
                  )}
                  {columns.map(col => (
                    <td key={col.key} className={`p-3 text-sm text-gray-300 ${col.className || ''}`}>
                      {col.render ? col.render(row) : String(row[col.key as keyof T])}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {pagination && totalPages > 1 && (
        <div className="flex items-center justify-between p-4 border-t border-white/10">
          <div className="text-sm text-gray-500">
            Page {currentPage} of {totalPages} ({filteredData.length} items)
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="p-2 rounded-lg border border-white/10 hover:bg-white/5 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="p-2 rounded-lg border border-white/10 hover:bg-white/5 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
